for rank,row in enumerate(rows,1):
 t,mode,n,nc,v,tier,thesis,win,status,three,six,funding,buffer,risks,alt,why,kill=row
 p=float(D[t]['finance']['最新价格']); prices=[round((z+nc)/n,2) for z in v] if mode=='EV' else v
 hurdle=f'目标2P={2*p:.2f}美元；完全稀释N={n}m、目标净现金={nc}m，所需EV=2P×N−净现金={2*p*n-nc:.2f}m。EV须由真实增长、可归属资产或成功率重估支持，不能拿TTM出售收益PE。' if mode=='EV' else f'目标2P={2*p:.2f}美元；经济稀释N={n}m，目标价格=正常化前瞻EPS×市场PE。成功分支见six_month_case，EPS必须已扣利息、优先分配及统一SBC代价；不使用基本股数冒充稀释股数。'
 ev=[s['id'] for s in S if s['ticker']==t]
 N.append(dict(rank=rank,ticker=t,tier=tier,reference_price=p,thesis=thesis,catalyst_window=win,catalyst_date_status=status,three_month_case=three,six_month_case=six,disappointment_price=prices[0],central_price=prices[1],upside_price=prices[2],multibagger_price=prices[3],double_hurdle_formula=hurdle,dilution_and_funding=funding,downside_buffer=buffer,risks=risks,closest_alternative=alt,why_preferred=why,reentry_or_kill_conditions=kill,evidence=ev,source_urls=[s['url'] for s in S if s['ticker']==t],local_original_paths=D[t]['sources'],model=dict(method=mode,fully_diluted_shares_m=n,target_net_cash_m=nc,enterprise_values_m=v if mode=='EV' else None,conditional_price_branches=v if mode=='EPS' else None,assumptions_not_forecasts=True),coverage='公司原文前部经营机制+情景定向资金/近期财报段落+对比定向片段；并非三份完整原文全量精读'))

method='独立盲审：先扫描全部245家公司类别、业务标签与10/12估值，后针对32家读取冻结公司/情景/对比原文片段及5个产业专题前部。第一轮以反向估值、现金归属和融资后权益过滤；未看X1–X4结论或旧实验名单。价格与市值采用冻结输入未逐条独立行情核验。所有3/6月价格为条件分支，不是预期回报或保证；4分支无机械概率加权。'
limits=['原文阅读是32家定向深挖关键机制和资金/时间，不是32家全部文件完整全文读完；部分批次输出截断，已通过后续小批读取主要缺口，仍不声称全段无遗漏。','外部原始和观点共26条，多为关键段落/公开摘要；约16家有本轮外部链接，但IONS/AVAV/ACMR/LEU/RDW/MRAM/ASTS决定性事实仍需下一轮独立外部复核。','署名多空意见覆盖VISN、CC、FLNC、AMBA、ADBE，未达到每家都有多空全文的标准；没有伪装已读收费研报。','融资后股数/净现金多为压力假设；ASTS、FLNC、LEU尤其需要资本结构专项签字，未签前列C或条件等待。','不能证明20家均有高概率六个月翻倍；A为相对优先，不是统计高概率；B含下行较小但时间不足，C仅右尾观察。','行业资料读取前部而非全文，外部买方验证不足；未使用旧实验最终名单。']
out=dict(role='X5_reverse_valuation',screened_count=len(U),deep_read_tickers=DEEP,nominations=N,reserves=[dict(ticker=t,reason=x) for t,x in RES.items()],method=method,limitations=limits,cutoff='2026-10-12 20:50 America/Los_Angeles',three_month_checkpoint='2027-01-12',six_month_checkpoint='2027-04-12')
eps_pe={'SMCI':14,'ENPH':23,'UCTT':19,'PNR':20,'ADBE':20,'AVAV':45,'ACMR':30,'MU':9,'NVDA':25}
for x in N:
 if x['ticker'] in eps_pe:
  pe=eps_pe[x['ticker']]; needed=2*x['reference_price']/pe
  x['double_hurdle_formula']+=f' 若PE={pe}，需要EPS={needed:.3f}、完全稀释归母净收益={needed*x["model"]["fully_diluted_shares_m"]:.1f}m；这不是当期已经实现的收益。'
 if x['ticker']=='ADBE':
  x['central_price']=352;x['upside_price']=480
  x['six_month_case']='前瞻FY2028经济EPS24×20=480，而非把当前调整EPS当GAAP；需要FY2027连续两季净收费增长支持远期约9.12bn稀释后归属利润。只要求收入温和增长但同时要求AI威胁折价收缩；触及中低、站稳中低。'
  x['model']['conditional_price_branches']=[168,352,480,630]
(R/'02_round1/X5_reverse.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
(R/'07_logs/X5_sources.json').write_text(json.dumps(S,ensure_ascii=False,indent=2),encoding='utf-8')
nom={x['ticker']:x for x in N}
with (R/'07_logs/X5_full245_screen.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['ticker','name','category','price_20261012','market_cap','forward_pe','ps','decision','company_specific_reason','coverage']);w.writeheader()
 for x in U:
  t=x['ticker']; fin=x['finance']; title=''
  if x['sources']['company']:
   p=R/x['sources']['company'][0]
   if p.exists(): title=p.read_text(encoding='utf-8-sig').splitlines()[0].lstrip('# ').strip()
  reason=nom[t]['thesis'] if t in nom else RES.get(t) or f"{x.get('business_tags') or title or x['category']}；当前市值{fin['市值']}、P/S{fin['P/S']}、远期PE{fin['Forward PE']}。只凭现有结构化输入尚不能建立2027-04前盈利/倍数同步翻倍且融资可闭合的优先证据，保留遗漏复活审查。"
  w.writerow(dict(ticker=t,name=x['name'],category=x['category'],price_20261012=fin['最新价格'],market_cap=fin['市值'],forward_pe=fin['Forward PE'],ps=fin['P/S'],decision='提名'+nom[t]['tier'] if t in nom else '候补' if t in RES else '首轮暂不优先',company_specific_reason=reason,coverage='32家定向原文阅读' if t in DEEP else '财务/业务标签/原文章名结构化扫描；非全文深读'))
md=['# X5 首轮独立反向估值与遗漏审查','',method,'','结论：优先核实 VISN、KYTX、SMCI、ENPH、UCTT、CC、AMPX；PNR、ADBE是下行质量较好但六个月翻倍时间证据较弱的跨行业替代。没有20家同等可靠的翻倍预测。排名兼顾窗口、权益门槛和左尾，不能解释为未来涨幅排序。','', '特别排除：ATKR现金收购95美元封住常规上行；PLAB海外JV现金不能全加归母，韩国8nm过晚；TE/WOLF融资结构不能用小市值掩盖。VISN已付15美元分配不属于新买入回报，2027H2退税不计六个月内收款。','','|顺位|公司|10/12价|失望|中枢|2倍成功分支|更强右尾|层级|','|---|---|---:|---:|---:|---:|---:|---|']
for x in N: md.append(f"|{x['rank']}|{x['ticker']}|{x['reference_price']}|{x['disappointment_price']}|{x['central_price']}|{x['upside_price']}|{x['multibagger_price']}|{x['tier']}|")
md+=['','EV模型所有金额为美元百万，先算归属企业值、加净现金后除完全稀释股数。EPS模型是成功时市场对前瞻盈利定价，不声称六个月已赚到全年EPS。中枢并非概率加权期望；失望价不是止损线或下限，所有公司均存在更差尾部。','']
for x in N:
 md += [f"## {x['rank']}. {x['ticker']} — {x['tier']}",x['thesis'],'',f"事件：{x['catalyst_window']} {x['catalyst_date_status']}",f"三月检查：{x['three_month_case']}",f"六月与触及/站稳区别：{x['six_month_case']}",f"翻倍反算：{x['double_hurdle_formula']}",f"融资与权益：{x['dilution_and_funding']}",f"缓冲：{x['downside_buffer']}",f"反证：{x['risks']}",f"对比 {x['closest_alternative']}：{x['why_preferred']}",f"退出/复活：{x['reentry_or_kill_conditions']}",f"本轮外部来源：{', '.join(x['evidence']) or '本轮未完成独立外部复核，引用冻结原文导航，需下一轮补核'}",'']
md+=['## 候补与复活','']+[f'- **{t}**：{r}' for t,r in RES.items()]+['','## 阅读和证据局限','']+[f'- {s}' for s in limits]+['','## 外部资料日志','']
for s in S: md.append(f"- {s['id']} [{s['ticker']} · {s['public_date']} · {s['author']}]({s['url']})；{s['access']}。{s['note']}")
(R/'02_round1/X5_reverse.md').write_text('\n\n'.join(md),encoding='utf-8')
notes=['# X5 原文定向阅读范围与笔记','',method,'','范围声明：32家公司每家读取公司原文开篇经营判断/决定性证据，情景稿近期两财报与资本结构相关检索段落、对比稿替代结论片段；VISN另读至第115行，覆盖交易范围/经营财务/资本占用。绝非96份全文全部精读。报告内旧目标价仅作为需反驳材料，没有直接平移到6个月。','']
for t in DEEP:
 notes += [f'## {t}',nom[t]['thesis']+' '+nom[t]['dilution_and_funding']+' '+nom[t]['risks'] if t in nom else RES[t], '原文导航：'+json.dumps(D[t]['sources'],ensure_ascii=False),'']
notes+=['## 产业阅读','定向读取冻结行业资料前16行：宽带接入/PON/DOCSIS（升级不等于行业增长、AI非VISN预算）；高端光罩（规格升级不等于光罩厂利润，客户内制上升）；设备子系统（OEM掌握系统价值、集成商承担库存）；冷却液水处理制冷剂（一次充装与持续耗材分开）；核酸药物免疫治疗（机制×支付患者×净价，早期临床非商业化）。未全文阅读，不把行业预测作为公司事实。','## 独立遗漏发现','ATKR交易现金封顶；PLAB合并现金672.8m大部在50.01%JV，归属净现金约417m；VISN退税晚于观察窗；SMCI基本646.9m与官方Q1非GAAP稀释761m有重大差；FLNC基本A类股数与全部经济权益不等；ACMR合并资金不能跨境全归母；MRAM工程资助不等于芯片订单；PNR10/1交易已经交割；BABA新股配售破坏机械回购叙述。']
(R/'07_logs/X5_reading_notes.md').write_text('\n\n'.join(notes),encoding='utf-8')
assert len(U)==245 and len({x['ticker'] for x in U})==245
assert len(N)==20 and len(RES)>=8 and len(DEEP)>=25
print(json.dumps(dict(screened=len(U),deep_targeted=len(DEEP),nominations=len(N),reserves=len(RES),external_entries=len(S)),ensure_ascii=False))
